`;function sTe(){if(document.getElementById("folha-print-css"))return;const a=document.createElement("style");a.id="folha-print-css",a.textContent=tTe,document.head.appendChild(a)}function iTe(a,t,s){const i=n=>n==null?void 0:n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"}),o={estatutario:"Estatutário",temporario:"Temporário",clt:"CLT",terceirizado:"Terceirizado",comissionado:"Comissionado"},l=a.verbas.map((n,d)=>`
